function amalByTitle(t) {
  return AMAL_LIST.find(x => x.title === t) || null;
}
function openAmal(i) {
  const a = AMAL_LIST[i];
  if (!a) return;
  let html = `<div class="stepbanner">${a.title}</div>`;
  html += `<p class="small">${a.kind} — 📖 ${a.source}</p>`;
  if (a.link) html += `<p class="small"><a class="external" href="${a.link}" target="_blank" rel="noopener">متن در سایت منبع ↗</a></p>`;
  html += `<div class="box amal"><p class="amal-text">${a.text}</p></div>`;
  if (a.namaz) html += `<div class="box gold"><h3>نماز سفارش‌شده</h3><p>${a.namaz}</p></div>`;
  if (a.note) html += `<div class="box"><p>${a.note}</p></div>`;
  $("amal-detail").innerHTML = html;
  go("amal");
}
